#pragma once

#include "World/Level/Block/BlockState.h"

#include <cstdint>

// MaterialType, in the game's order (names at 0x14F185120, 26.60)
enum class BlockMaterialType : uint8_t {
    Air,
    Dirt,
    Wood,
    Metal,
    Grate,
    Water,
    Lava,
    Leaves,
    Plant,
    SolidPlant,
    Fire,
    Glass,
    Explosive,
    Ice,
    PowderSnow,
    Cactus,
    Portal,
    StoneDecoration,
    Bubble,
    Barrier,
    DecorationSolid,
    ClientRequestPlaceholder,
    StructureVoid,
    Solid,
    NonSolid,
};

// the material the game gives each block: generated by tools/gen_block_materials.py
namespace BlockMaterial {
    // set on leaves, glass, explosive, ice and cactus only
    inline constexpr uint8_t FLAG_BIT0 = 1;
    // water, lava and the bubble column
    inline constexpr uint8_t FLAG_LIQUID = 2;
    // the flag LevelChunk::getAboveTopSolidBlock stops on
    inline constexpr uint8_t FLAG_SOLID = 4;

    // false for a name the game does not register: custom blocks have no entry
    bool find(const BlockState &state, BlockMaterialType &type);

    uint8_t flagsOf(BlockMaterialType type);

    // 0 for a name the game does not register
    uint8_t flagsOf(const BlockState &state);

    // bit 0x40000 of the block's properties (BlockLegacy +304): set by the base constructor, cleared by most
    // classes with their own shape; false for a name the game does not register
    bool hasDefaultProperty(const BlockState &state);
}
